package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.manualincident.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class ManualIncidentTest {
    static final String ASSET="55000000-0000-4000-8000-000000000001";
    @Test void preservesRawTitleAndExplicitSourceWithoutMonitoringOrTicketClaims(){var value=new ManualIncident("  电话报障😀 原文  ",ManualIncident.Severity.HIGH,ASSET,1);assertEquals("  电话报障😀 原文  ",value.title());assertEquals("MANUAL",value.sourceState());assertEquals("SELF_REPORTED",value.verificationStatus());assertEquals("REGISTERED_ONLY",value.registrationStatus());assertNull(value.monitorState());assertNull(value.dispositionState());assertNull(value.ticketPriority());assertFalse(value.ticketAutomaticallyCreated());}
    @Test void allFiveContractSeveritiesRequireExplicitCodesAndDoNotGrantAutomaticRecovery(){for(var severity:ManualIncident.Severity.values()){assertEquals(severity,ManualIncident.Severity.fromCode(severity.code()));assertFalse(severity.label().isBlank());assertFalse(new ManualIncident("现场观察",severity,ASSET,1).monitoringRecoveryApplicable());}assertEquals(5,ManualIncident.Severity.values().length);assertEquals("严重",ManualIncident.Severity.fromCode("high").label());}
    @Test void noSeverityIsInferredFromMissingUnknownOrMonitoringStatus(){for(String code:new String[]{null,"","none","unknown","normal","PROBLEM","RECOVERED","critical","HIGH"})assertEquals(400,assertThrows(DomainException.class,()->ManualIncident.Severity.fromCode(code)).status);assertThrows(DomainException.class,()->new ManualIncident("title",null,ASSET,1));}
    @Test void unicodeMaximumUsesCodePointsAndNoNormalization(){assertEquals(200,new ManualIncident("😀".repeat(200),ManualIncident.Severity.INFO,ASSET,1).title().codePointCount(0,400));assertThrows(DomainException.class,()->new ManualIncident("😀".repeat(201),ManualIncident.Severity.INFO,ASSET,1));assertNotEquals(new ManualIncident("é",ManualIncident.Severity.INFO,ASSET,1),new ManualIncident("e\u0301",ManualIncident.Severity.INFO,ASSET,1));}
    @Test void rejectsBlankControlsAndMalformedUnicode(){for(String title:new String[]{null,""," \t ","\ufeff\u00a0","line\nnext","tab\tvalue","x\u0000","x\u007f","x\u0085","x\ud800"})assertThrows(DomainException.class,()->new ManualIncident(title,ManualIncident.Severity.AVERAGE,ASSET,1));}
    @Test void assetIdentityAndObservedVersionAreExplicitAndSafe(){for(String asset:new String[]{null,"","1-1-1-1-1","../asset",ASSET+" "})assertThrows(DomainException.class,()->new ManualIncident("title",ManualIncident.Severity.WARNING,asset,1));for(long version:new long[]{0,-1,Long.MAX_VALUE,9007199254740992L})assertThrows(DomainException.class,()->new ManualIncident("title",ManualIncident.Severity.WARNING,ASSET,version));assertEquals(9007199254740991L,new ManualIncident("title",ManualIncident.Severity.WARNING,ASSET,9007199254740991L).observedAssetVersion());assertEquals("aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",new ManualIncident("title",ManualIncident.Severity.WARNING,"AAAAAAAA-AAAA-4AAA-8AAA-AAAAAAAAAAAA",1).assetId());}
    @Test void currentInternalRolesAreScopedToSameTenant(){for(String role:new String[]{"msp","padmin"})assertDoesNotThrow(()->ManualIncidentAccess.require(new Membership("actor","tenant",role,7,true),7,"tenant"));assertEquals(404,assertThrows(DomainException.class,()->ManualIncidentAccess.require(new Membership("actor","tenant","msp",7,true),7,"other")).status);}
    @Test void customersAndUnknownRolesCannotRegisterInternalManualSources(){for(String role:new String[]{"viewer","tadmin","unknown",null})assertEquals(403,assertThrows(DomainException.class,()->ManualIncidentAccess.require(new Membership("actor","tenant",role,7,true),7,"tenant")).status);}
    @Test void staleInactiveAndMissingMembershipFailClosed(){assertEquals(401,assertThrows(DomainException.class,()->ManualIncidentAccess.require(null,7,"tenant")).status);for(var member:new Membership[]{new Membership("actor","tenant","msp",7,false),new Membership("actor","tenant","msp",8,true),new Membership("","tenant","msp",7,true),new Membership("actor","","msp",7,true)})assertEquals(401,assertThrows(DomainException.class,()->ManualIncidentAccess.require(member,7,"tenant")).status);}
    @Test void technicalRegistrationTimestampIsNotAnObservationOrRecoveryTime(){var report=new ManualIncident("现场故障",ManualIncident.Severity.DISASTER,ASSET,3);var entry=new ManualIncidentRepository.Entry("id","tenant",report,"资产登记名","actor",java.time.Instant.parse("2026-10-03T00:00:00Z"));assertNotNull(entry.registeredAt());assertNull(entry.incident().observedAt());assertNull(entry.incident().recoveredAt());assertFalse(entry.incident().monitoringRecoveryApplicable());assertEquals("NOT_CONFIRMED",entry.incident().manualRecoveryStatus());}
}
